#include <locale>
#include <fmt/format.h>
struct punctuation : std::numpunct<char> {
  char do_thousands_sep() const override { return ','; }
  std::string do_grouping() const override { return "\3"; }
};
int main() {
  std::locale::global(std::locale(std::locale::classic(), new punctuation));
  for (double value : {-119.921, 2194.139, -57.639, -5.980, -2.119, 0.295, 1.295}) {
    auto text = fmt::format("{:19.3Lf}", value);
    fmt::print("value={} |{}| width={}\n", value, text, text.size());
  }
}
