cd /testbed && git --no-pager diff --stat && python3 - <<'PY' | patch -p1
import difflib
from pathlib import Path
path = Path('test/xchar-test.cc')
old = path.read_text()
addition = '''TEST(locale_test, localized_float_alignment) {
  auto loc = std::locale(std::locale(), new numpunct<char>());
  const std::pair<double, const char*> cases[] = {
      {-119.921, "-119?921"}, {2194.139, "2~194?139"},
      {-57.639, "-57?639"},   {-5.980, "-5?980"},
      {-2.119, "-2?119"},     {0.295, "0?295"},
      {1.295, "1?295"},       {0.0, "0?000"},
      {1230.0, "1~230?000"}};
  for (auto test : cases) {
    EXPECT_EQ(fmt::format("{:>19}", test.second),
              fmt::format(loc, "{:19.3Lf}", test.first));
    EXPECT_EQ(fmt::format("{:<19}", test.second),
              fmt::format(loc, "{:<19.3Lf}", test.first));
    EXPECT_EQ(fmt::format("{:^19}", test.second),
              fmt::format(loc, "{:^19.3Lf}", test.first));
  }
  EXPECT_EQ("              1?295", fmt::format(loc, "{:19.3Lf}", 1.295f));
  EXPECT_EQ("              1?295", fmt::format(loc, "{:19.3Lf}", 1.295L));
  EXPECT_EQ("         1?23456789", fmt::format(loc, "{:19.8Lf}", 1.23456789));
  EXPECT_EQ("              1.295", fmt::format(loc, "{:19.3f}", 1.295));
  auto ungrouped_loc = std::locale(std::locale(), new no_grouping<char>());
  EXPECT_EQ("              1.295",
            fmt::format(ungrouped_loc, "{:19.3Lf}", 1.295));
  auto small_grouping_loc = std::locale(std::locale(), new small_grouping<char>());
  EXPECT_EQ("  1,2.3456", fmt::format(small_grouping_loc, "{:10.4Lf}", 12.3456));
}

TEST(locale_test, localized_wfloat_alignment) {
  auto loc = std::locale(std::locale(), new numpunct<wchar_t>());
  EXPECT_EQ(L"              0?295", fmt::format(loc, L"{:19.3Lf}", 0.295));
  EXPECT_EQ(L"              1?295", fmt::format(loc, L"{:19.3Lf}", 1.295));
  EXPECT_EQ(L"           -119?921", fmt::format(loc, L"{:19.3Lf}", -119.921));
  EXPECT_EQ(L"          2~194?139", fmt::format(loc, L"{:19.3Lf}", 2194.139));
  EXPECT_EQ(L"1?295              ", fmt::format(loc, L"{:<19.3Lf}", 1.295));
  EXPECT_EQ(L"       1?295       ", fmt::format(loc, L"{:^19.3Lf}", 1.295));
  EXPECT_EQ(L"              1?295", fmt::format(loc, L"{:19.3Lf}", 1.295L));
}

'''
marker = 'TEST(locale_test, format) {'
assert old.count(marker) == 1
new = old.replace(marker, addition + marker)
print(''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True), fromfile='a/test/xchar-test.cc', tofile='b/test/xchar-test.cc')), end='')
PY
cmake -B build -S . > build/configure.log && cmake --build build --parallel 4 --target xchar-test > build/xchar-build.log 2>&1 && build/bin/xchar-test --gtest_filter='locale_test.localized*float_alignment' > build/localized-alignment-baseline.log 2>&1; status=$?; tail -65 build/localized-alignment-baseline.log; exit "$status"

